<script>$(function(){const form=$('#forecast-filter'),list=$('#forecast-list'),pagination=$('#forecast-pagination'),summary=$('#forecast-summary'),stages=$('#forecast-stages'),conversionSummary=$('#conversion-summary'),conversionStages=$('#conversion-stages'),dataUrl=@json(route('crm.forecast.data')),indexUrl=@json(route('crm.forecast.index')),owner=$('#forecast-owner'),team=$('#forecast-team');window.erpInitSelect2(owner,{theme:'bootstrap-5',allowClear:true,placeholder:'ทุกคนที่มีสิทธิ์',ajax:{url:@json(route('crm.forecast.owner-options')),dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1,team_id:team.val()||''}),processResults:d=>d}});team.on('change',()=>owner.val(null).trigger('change'));let request;const money=value=>value===null?'-':Number(value).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});function load(page,push){if(request)request.abort();const params=new URLSearchParams(new FormData(form[0]));if(page>1)params.set('page',page);list.attr('aria-busy','true').html('<div class="col-12 text-center text-secondary py-5"><span class="spinner-border spinner-border-sm me-2"></span>กำลังโหลด Forecast...</div>');request=$.getJSON(dataUrl,params.toString()).done(function(data){list.html(data.html).attr('aria-busy','false');pagination.html(data.pagination);summary.text(data.total?'แสดง '+data.from+'–'+data.to+' จาก '+data.total+' คน':'ไม่พบข้อมูล');Object.entries(data.summary).forEach(([key,value])=> $('[data-summary="'+key+'"]').text(['coverage'].includes(key)?(value===null?'-':Number(value).toLocaleString('th-TH',{maximumFractionDigits:1})+'%'):money(value)));const labels={NEW:'ลูกค้าเป้าหมายใหม่',CONTACTED:'ติดต่อแล้ว',QUALIFIED:'ผ่านการคัดกรอง',PROPOSAL:'เสนอขาย',NEGOTIATION:'เจรจา'};stages.html(data.stages.length?data.stages.map(row=>'<div class="col-6 col-lg"><div class="border rounded-3 p-3 h-100"><span class="small text-secondary">'+(labels[row.stage]||row.stage)+'</span><strong class="d-block">'+money(row.pipeline)+'</strong><small>Forecast '+money(row.forecast)+' · '+row.opportunity_count+' รายการ</small></div></div>').join(''):'<div class="col-12 text-center text-secondary py-3">ไม่มี Pipeline ในเดือนนี้</div>');const performance=data.performance,metrics=[['Opportunity ใหม่',performance.created],['Won',performance.won],['Lost',performance.lost],['Win rate',performance.win_rate===null?'-':Number(performance.win_rate).toFixed(1)+'%'],['Sales cycle เฉลี่ย',performance.average_cycle_days===null?'-':Number(performance.average_cycle_days).toFixed(1)+' วัน']];conversionSummary.html(metrics.map(row=>'<div class="col-6 col-lg"><div class="border rounded-3 p-3 text-center h-100"><span class="small text-secondary">'+row[0]+'</span><strong class="d-block">'+row[1]+'</strong></div></div>').join(''));const durations=Object.fromEntries(performance.durations.map(row=>[row.stage,row]));conversionStages.html(performance.funnel.map(row=>{const duration=durations[row.stage];return '<div class="col-6 col-lg"><div class="border rounded-3 p-3 h-100"><span class="small text-secondary">'+(labels[row.stage]||row.stage)+'</span><strong class="d-block">'+row.reached+' รายการ</strong><small>ไปขั้นถัดไป '+(row.conversion===null?'-':Number(row.conversion).toFixed(1)+'%')+' · ใช้เวลาเฉลี่ย '+(duration?Number(duration.average_days).toFixed(1)+' วัน':'-')+'</small></div></div>';}).join(''));function insight(selector,rows,detail){const box=$(selector).empty();if(!rows.length){box.append($('<div class="text-secondary small py-2"></div>').text('ไม่มีข้อมูลในเดือนนี้'));return;}rows.forEach(row=>box.append($('<div class="border rounded-3 p-3"></div>').append($('<strong class="d-block text-break"></strong>').text(row.label),$('<small class="text-secondary"></small>').text(detail(row)))));}insight('#insight-sources',data.insights.sources,row=>row.opportunity_count+' Opportunity · Pipeline '+money(row.pipeline)+' · Won '+row.won_count);insight('#insight-products',data.insights.products,row=>row.opportunity_count+' Opportunity · '+row.interest_count+' ความสนใจ · งบ '+money(row.budget));insight('#insight-lost',data.insights.lost,row=>row.opportunity_count+' Opportunity · มูลค่า '+money(row.lost_value));$('#risk-count').text(data.risks.length+' ดีล');const riskList=$('#risk-list').empty();if(!data.risks.length)riskList.append('<div class="col-12 text-center text-secondary py-3">ไม่พบ Opportunity เสี่ยงในขอบเขตนี้</div>');data.risks.forEach(row=>{const body=$('<div class="card-body p-3"></div>').append($('<div class="d-flex justify-content-between gap-2"></div>').append($('<strong class="text-break"></strong>').text(row.title),$('<span class="badge app-status-warning flex-shrink-0"></span>').text(money(row.expected_value))),$('<div class="small text-secondary text-break mt-1"></div>').text([row.customer,row.owner].filter(Boolean).join(' · ')),$('<div class="d-flex flex-wrap gap-1 mt-2"></div>').append(row.reasons.map(reason=>$('<span class="badge app-status-danger"></span>').text(reason))),$('<div class="d-flex justify-content-between align-items-center mt-2"></div>').append($('<small class="text-secondary"></small>').text('คาดปิด '+(row.expected_close_date||'-')+' · Next '+(row.next_action_at||'-')),$('<a class="btn btn-sm btn-app-soft"><i class="bx bx-show me-1" aria-hidden="true"></i>ตรวจสอบ</a>').attr('href',row.url)));riskList.append($('<div class="col-12 col-xl-6"><article class="card h-100"></article></div>').find('article').append(body).end());});if(push)history.pushState({},'',indexUrl+'?'+params.toString());}).fail(function(xhr,status){if(status==='abort')return;list.attr('aria-busy','false').html('<div class="col-12"><div class="alert alert-danger">โหลด Forecast ไม่สำเร็จ <button class="btn btn-sm btn-outline-danger ms-2 js-retry" type="button">ลองใหม่</button></div></div>');});}form.on('submit',e=>{e.preventDefault();load(1,true);});pagination.on('click','a',function(e){e.preventDefault();load(Number(new URL(this.href).searchParams.get('page')||1),true);});list.on('click','.js-retry',()=>load(1,false));window.addEventListener('popstate',()=>location.reload());load(Number(new URL(location.href).searchParams.get('page')||1),false);});</script>
